class Solution {
    long score(vector<int>& p) {
        long s = 0;
        for (int i = 0; i < (int)p.size(); i++) {
            bool dbl = (i >= 1 && p[i-1] == 10) || (i >= 2 && p[i-2] == 10);
            s += dbl ? 2L * p[i] : p[i];
        }
        return s;
    }
public:
    int isWinner(vector<int>& player1, vector<int>& player2) {
        long a = score(player1), b = score(player2);
        return a > b ? 1 : (b > a ? 2 : 0);
    }
};

