class Solution {
    private long score(int[] p) {
        long s = 0;
        for (int i = 0; i < p.length; i++) {
            boolean dbl = (i >= 1 && p[i-1] == 10) || (i >= 2 && p[i-2] == 10);
            s += dbl ? 2L * p[i] : p[i];
        }
        return s;
    }
    public int isWinner(int[] player1, int[] player2) {
        long a = score(player1), b = score(player2);
        return a > b ? 1 : (b > a ? 2 : 0);
    }
}

